(()=>{'use strict';if(window.__purchaseRangeCalendar)return;window.__purchaseRangeCalendar=true;
const pad=n=>String(n).padStart(2,'0'),fmt=d=>[d.getFullYear(),pad(d.getMonth()+1),pad(d.getDate())].join('-'),parse=s=>s?new Date(s+'T12:00:00'):null;
function init(){const page=document.querySelector('#purchase'),filters=page?.querySelector('.module-toolbar .filters');if(!filters||filters.dataset.rangeCalendar)return;const dates=[...filters.querySelectorAll('input[type=date]')];if(dates.length<2)return;filters.dataset.rangeCalendar='1';
const [start,end]=dates;start.style.display='none';end.style.display='none';
const root=document.createElement('div');root.className='pcal-root';root.innerHTML='<button type="button" class="pcal-trigger"><span>발주기간 선택</span><span>▦</span></button><div class="pcal-pop" hidden></div>';start.before(root);
const trigger=root.querySelector('.pcal-trigger'),pop=root.querySelector('.pcal-pop');let a=parse(start.value),b=parse(end.value),base=new Date(new Date().getFullYear(),new Date().getMonth(),1),oldA,oldB;
const close=()=>{pop.hidden=true};const update=()=>{trigger.firstElementChild.textContent=a&&b?fmt(a)+' ~ '+fmt(b):'발주기간 선택'};
function draw(){pop.replaceChildren();const presets=document.createElement('div');presets.className='pcal-presets';
const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),y=today.getFullYear(),m=today.getMonth(),d=today.getDate(),monday=x=>{const z=new Date(x);z.setDate(z.getDate()-((z.getDay()+6)%7));return z};
['올해','오늘까지','오늘','전일','주간','전주','당월','이전달'].forEach(t=>{const x=document.createElement('button');x.type='button';x.textContent=t;x.onclick=()=>{if(t==='올해'){a=new Date(y,0,1);b=new Date(y,11,31)}else if(t==='오늘까지'){a=new Date(y,0,1);b=today}else if(t==='오늘'){a=today;b=new Date(today)}else if(t==='전일'){a=new Date(y,m,d-1);b=new Date(a)}else if(t==='주간'){a=monday(today);b=new Date(a);b.setDate(b.getDate()+6)}else if(t==='전주'){b=monday(today);b.setDate(b.getDate()-1);a=new Date(b);a.setDate(a.getDate()-6)}else if(t==='당월'){a=new Date(y,m,1);b=new Date(y,m+1,0)}else{a=new Date(y,m-1,1);b=new Date(y,m,0)}base=new Date(a.getFullYear(),a.getMonth(),1);draw()};presets.append(x)});pop.append(presets);
const months=document.createElement('div');months.className='pcal-months';for(let k=0;k<2;k++){const dt=new Date(base.getFullYear(),base.getMonth()+k,1),yy=dt.getFullYear(),mm=dt.getMonth(),part=document.createElement('section');part.className='pcal-month';const head=document.createElement('header'),prev=document.createElement('button'),next=document.createElement('button');prev.type=next.type='button';prev.textContent='‹';next.textContent='›';prev.onclick=()=>{base=new Date(base.getFullYear(),base.getMonth()-1,1);draw()};next.onclick=()=>{base=new Date(base.getFullYear(),base.getMonth()+1,1);draw()};head.append(prev,document.createTextNode(yy+'.'+pad(mm+1)),next);part.append(head);const days=document.createElement('div');days.className='pcal-days';['일','월','화','수','목','금','토'].forEach(t=>{const el=document.createElement('b');el.textContent=t;days.append(el)});for(let n=0;n<new Date(yy,mm,1).getDay();n++)days.append(document.createElement('i'));for(let n=1;n<=new Date(yy,mm+1,0).getDate();n++){const date=new Date(yy,mm,n),key=fmt(date),el=document.createElement('button');el.type='button';el.textContent=n;if((a&&fmt(a)===key)||(b&&fmt(b)===key))el.className='chosen';else if(a&&b&&date>a&&date<b)el.className='between';el.onclick=()=>{if(!a||b){a=date;b=null}else if(date<a){b=a;a=date}else b=date;draw()};days.append(el)}part.append(days);months.append(part)}pop.append(months);
const foot=document.createElement('footer'),summary=document.createElement('span'),cancel=document.createElement('button'),ok=document.createElement('button');summary.textContent=a?fmt(a)+(b?' ~ '+fmt(b):' ~ 종료일 선택'):'기간을 선택하세요';cancel.type=ok.type='button';cancel.textContent='취소';ok.textContent='확인';ok.className='pcal-confirm';cancel.onclick=()=>{a=oldA;b=oldB;close()};ok.onclick=()=>{if(!a||!b)return;start.value=fmt(a);end.value=fmt(b);update();close();page.querySelector('.qpu-search')?.click()};foot.append(summary,cancel,ok);pop.append(foot)}
trigger.onclick=()=>{if(!pop.hidden){close();return}oldA=a;oldB=b;base=a?new Date(a.getFullYear(),a.getMonth(),1):new Date(nowYear(),new Date().getMonth(),1);draw();pop.hidden=false};
function nowYear(){return new Date().getFullYear()}
page.querySelector('.qpu-clear')?.addEventListener('click',()=>{a=b=null;update();close()});document.addEventListener('pointerdown',e=>{if(!pop.hidden&&!root.contains(e.target))close()});update()}
const style=document.createElement('style');style.textContent=`.pcal-root{position:relative;grid-column:2/span 2;min-width:0;max-width:310px;width:100%;justify-self:start;z-index:60}.pcal-trigger{width:100%;height:38px;border:1px solid #cedbeb;border-radius:7px;background:#fbfdff;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 12px;cursor:pointer;color:#2e4561;font-size:12px}.pcal-pop{position:absolute;z-index:1000;left:0;top:42px;width:min(450px,94vw);background:#fff;border:1px solid #ccdaea;border-radius:6px;box-shadow:0 12px 28px #192c4933;padding:9px}.pcal-pop[hidden]{display:none}.pcal-presets{display:flex;gap:3px;justify-content:space-between;margin-bottom:8px}.pcal-presets button{font-size:11px;white-space:nowrap;border:1px solid #e1e7f0;border-radius:3px;padding:5px;background:#f8fbff;cursor:pointer}.pcal-months{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pcal-month header{display:flex;justify-content:space-between;align-items:center;font-size:12px;font-weight:600;padding:4px}.pcal-month header button{border:0;background:transparent;font-size:18px;cursor:pointer}.pcal-days{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;text-align:center}.pcal-days b,.pcal-days button{font-size:11px;min-height:27px;display:grid;place-items:center}.pcal-days button{border:0;background:#eff5fc;cursor:pointer;border-radius:3px}.pcal-days button.chosen{background:#2171e8;color:#fff}.pcal-days button.between{background:#dbeafe}.pcal-pop footer{border-top:1px solid #e2e8f0;margin-top:8px;padding-top:8px;display:flex;align-items:center;justify-content:flex-end;gap:6px}.pcal-pop footer span{margin-right:auto;color:#718198;font-size:10px}.pcal-pop footer button{border:1px solid #cbd5e1;background:#fff;border-radius:4px;padding:5px 10px;cursor:pointer}.pcal-pop footer .pcal-confirm{background:#2775e7;color:#fff}`;document.head.append(style);new MutationObserver(init).observe(document.body,{childList:true,subtree:true});init();
})();